<tr><td style="padding:11px 0;border-top:1px solid #ebe4d8;vertical-align:top;font-size:13px;color:#6a716d;width:36%;padding-right:16px;border-bottom:1px solid #ebe4d8;">Refund due</td><td style="padding:11px 0;border-top:1px solid #ebe4d8;vertical-align:top;font-weight:600;border-bottom:1px solid #ebe4d8;">{{booking.refund_due}}</td></tr>
